                EXPECT_QUOTE();
                levelScriptName = parser.ReadAsStringUntilString("\"");
                EXPECT_QUOTE();
            } else if (token == "NewMap") {
                NProgressDisplay::DisplayProgress("Loading maps", -1.0f, false, false);
                newMap = parser.ReadAsInteger();
            } else if (token == "EndMap") {
                if (newMap) {
